const icon_bitmap_t* icon_get_bitmap(int icon_id) {
    if (icon_id < 0 || icon_id >= ICON_TOTAL_COUNT) return 0;
    if (!icon_table[icon_id].data) return 0;
    return &icon_table[icon_id];
}